<?php
declare(strict_types=1); namespace App\Http\Controllers\Classrooms; use App\Http\Controllers\Controller; use App\Models\Classroom; use App\Services\Classrooms\ClassroomService; use Illuminate\Http\RedirectResponse; use Illuminate\Http\Request;
class ClassroomStatusController extends Controller {public function activate(Request $r,Classroom $classroom,ClassroomService $s):RedirectResponse{$r->user()->can('classrooms.activate')?:abort(403);$s->setActive($r->user(),$classroom,true);return back()->with('success','Rombel berhasil diaktifkan.');}public function deactivate(Request $r,Classroom $classroom,ClassroomService $s):RedirectResponse{$r->user()->can('classrooms.activate')?:abort(403);$s->setActive($r->user(),$classroom,false);return back()->with('success','Rombel berhasil dinonaktifkan.');}}
